import 'package:flutter/material.dart';import '../../core/colors/app_colors.dart';class BmiCalculatorScreen extends StatefulWidget {  const BmiCalculatorScreen({super.key});  @override  State<BmiCalculatorScreen> createState() => _BmiCalculatorScreenState();}final _heightController = TextEditingController();final _weightController = TextEditingController();final _formKey = GlobalKey<FormState>();double? _bmi;String? _category = '';Color _categoryColor = AppColors.normal;class _BmiCalculatorScreenState extends State<BmiCalculatorScreen> {  void calculate() {    final heightCm = double.parse(_heightController.text);    final weightKg = double.parse(_weightController.text);    final heightM = heightCm / 100;    final bmi = weightKg / (heightM * heightM);    final (category, color) = _classify(bmi);    setState(() {      _bmi = bmi;      _category = category;      _categoryColor = color;    });   }  (String, Color) _classify(double bmi) {    if (bmi < 18.5)      return ('Underweight', AppColors.underweight);    else if (bmi < 25)      return ('Normal', AppColors.normal);    else if (bmi < 30)      return ('Overweight', AppColors.overweight);    else      return ('Obese', AppColors.obese);  }  @override  Widget build(BuildContext context) {    return Scaffold();  }}